const fpClamp=(value,min=0,max=1)=>Math.max(min,Math.min(max,value));
const fpText=(x,y,value,size=18,color='#172e34',anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" fill="${color}" font-family="Arial,sans-serif" font-size="${size}">${value}</text>`;
const fpSvg=(content,label)=>svg(content,label,'0 0 640 300');
const fpImage=(file,label,height=250)=>`<figure style="margin:0;width:100%;text-align:center"><img src="assets/${file}" alt="${label}" style="max-width:100%;width:auto;height:auto;max-height:${height}px;object-fit:contain"><figcaption style="font-size:12px;color:#536c69;margin:8px 0">${label}</figcaption></figure>`;
