function fpCoinPosition(path,progress){const f=fpClamp(progress,0,4),i=Math.floor(f),a=path[i],b=path[Math.min(i+1,4)];return a+(b-a)*(f-i)}
function fpCoinScene(s,f){if(s===4){const endings=[[12],[8,9],[4,5,6],[0,1,2,3],[0]];let out=fpText(320,28,'За четыре броска: все возможные итоги',21);endings.forEach((values,i)=>{const y=55+i*43;out+=`<rect x="75" y="${y-18}" width="490" height="35" rx="8" fill="${i===1||i===2?'#e3efe6':'#f1f2e9'}"/>`+fpText(143,y+5,i+' раз Y',19)+fpText(380,y+5,values.join(', '),20)});return fpSvg(out,'Таблица итоговых клеток для каждого количества Y: ноль — 12; один — 8 или 9; два — 4,5,6; три — 0,1,2,3; четыре — 0')}
const X=n=>81.5+n*37;let out='';const progress=s===0?0:s===1?Math.min(f,1):s===2?Math.min(f,4):4;for(let row=0;row<2;row++){const y=90+row*130,name=row?'Дима':'Тоня',path=row?FOUR_COIN_PATHS.dima:FOUR_COIN_PATHS.tonya;out+=fpText(52,y-29,name,20)+`<ellipse cx="81" cy="${y+16}" rx="27" ry="22" fill="#e5eee1"/>`+fpText(81,y+20,'старт',11);for(let n=1;n<=12;n++)out+=`<rect x="${100+(n-1)*37}" y="${y}" width="37" height="32" fill="${n===(row?8:4)?'#f7dfb5':'#fffefa'}" stroke="#879a90"/>`+fpText(X(n),y+22,n,16);
const p=s===0?0:s===1?(row?0:Math.min(f,1)):s===2?(row?0:progress):s===3?(row?Math.min(f,4):4):4;const done=Math.floor(p);let points=path.slice(0,done+1).map(n=>`${X(n)},${y-10}`);points.push(`${X(fpCoinPosition(path,p))},${y-10}`);if(p)out+=`<polyline points="${points.join(' ')}" fill="none" stroke="${row?'#e9693e':'#237e79'}" stroke-width="3"/>`;out+=`<circle cx="${X(fpCoinPosition(path,p))}" cy="${y-10}" r="9" fill="${row?'#e9693e':'#237e79'}"/>`;out+=fpText(320,y+56,s===0?'4 броска · цель '+(row?8:4):s===1?'X: +3 · Y: −1, но не дальше старта':row?'X → X → X → Y · один Y':'X → X → Y → Y · два Y',17)}if(s===5)out+=fpText(560,149,'2 + 1 = 3',20,'#237e79');return fpSvg(out,'Дорожка с отдельным стартом перед клеткой 1. Тоня приходит на 4, Дима на 8')}
