function fpFruitScene(s,f){const count=Math.min(s,5);let out='';FOUR_FRUITS.forEach((fruit,c)=>out+=fpText(190+c*86,24,fruit,13));for(let r=0;r<5;r++){const y=40+r*44;out+=fpText(86,y+28,FOUR_FRUIT_PEOPLE[r],19);for(let c=0;c<5;c++){const allowed=FOUR_FRUIT_PREFS[r].includes(c),own=r<count&&FOUR_FRUIT_ASSIGNMENT[r]===c,owner=FOUR_FRUIT_ASSIGNMENT.indexOf(c),taken=owner<count&&owner!==r;out+=`<rect x="${151+c*86}" y="${y}" width="78" height="38" rx="7" fill="${own?'#cde5d6':allowed&&!taken?'#f4eedc':'#f4f4ee'}" stroke="${own?'#237e79':'#d9dfd2'}"/>`+fpText(190+c*86,y+27,own?'✓ '+FOUR_FRUIT_ICONS[c]:allowed&&!taken?FOUR_FRUIT_ICONS[c]:allowed?'×':'—',own?20:22,taken?'#8d9a91':'#172e34')}}out+=fpText(320,289,s===0?'Цветная клетка — ребёнок любит этот фрукт':s===6?'Пять детей · пять разных фруктов · Боря взял яблоко':'Распределено фруктов: '+count+' из 5',17);return fpSvg(out,'Таблица предпочтений и последовательного исключения уже взятых фруктов')}
