function fpDiskScene(s,f){if(s===0)return `<div style="width:100%;display:flex;flex-direction:column;align-items:center;gap:10px"><img src="assets/disks-original.png" style="height:155px;width:auto" alt="Исходная башня из восьми дисков"><img src="assets/disks-options.png" style="max-width:100%;height:auto;max-height:140px" alt="Пять оригинальных вариантов башни: А, Б, В, Г, Д"></div>`;let out='';const operation=fpClamp(s-2,0,3),before=s===1?FOUR_DISK_STATES[0]:s>=6?FOUR_DISK_STATES[4]:FOUR_DISK_STATES[operation],rank=s>=2&&s<=5?FOUR_DISK_REMOVE_RANKS[operation]:0,t=s>=2&&s<=5?fpClamp(f/2.5):0,slide=fpClamp(t/.55),fall=fpClamp((t-.55)/.45);before.forEach((id,index)=>{const removed=index===rank-1;const x=removed?280+slide*180:280,y=258-index*25+(rank&&index>=rank?fall*25:0),opacity=removed?1-slide*.4:1;out+=`<g opacity="${opacity}"><rect x="${x}" y="${y-22}" width="90" height="24" fill="${FOUR_DISK_COLORS[id]}" stroke="#172e34"/><ellipse cx="${x+45}" cy="${y-22}" rx="45" ry="7" fill="${FOUR_DISK_COLORS[id]}" stroke="#172e34"/>${fpText(x-25,y-9,rank&&!removed&&index>=rank&&t>=1?index:index+1,16,removed?'#bd4f2a':'#536c69')}</g>`});out+=fpText(112,61,'Считаем снизу ↑',18)+fpText(320,290,s===1?'Нижний диск — первый':s>=6?'Сверху вниз: синий · белый · оранжевый · синий':'Удаляем диск №'+rank+' снизу',18);if(rank)out+=fpText(505,70,t<1?'Убираем':'Убрали',17,'#bd4f2a');return fpSvg(out,'Башня после последовательных удалений. На каждом шаге диски считаются снизу заново')}
const FOUR_FISH_FIRST=[5,5,4,4,4,4],FOUR_FISH_SECOND=[4,4,5,5,5,5];
function fpFishScene(s,f){if(s===0)return fpSvg(fpText(210,130,'🐧',78)+fpText(430,130,'🐧',78)+fpText(320,50,'Каждый день вместе — 9 рыб',23)+fpText(210,225,'Всего 26 рыб',22)+fpText(430,225,'Всего ? рыб',22),'Два птенца. Первый съел 26 рыб, количество дней неизвестно');if(s===1){let out=fpText(320,35,'По 4 или 5 рыб за день',22);[[5,20,25],[6,24,30],[7,28,35]].forEach(([days,min,max],i)=>{const y=72+i*68;out+=`<rect x="110" y="${y}" width="420" height="53" rx="10" fill="${days===6?'#d9eadb':'#f1eadf'}"/>`+fpText(180,y+33,days+' дней',22)+fpText(370,y+33,min+'–'+max+' рыб',22)});return fpSvg(out,'Пять дней дают не больше 25 рыб; семь — не меньше 28. Подходят шесть дней')}
let out=fpText(320,27,'Шесть дней',22);const reveal=s===2?0:2;for(let d=0;d<6;d++){const x=77+d*90,a=d<reveal?5:4,b=9-a;out+=fpText(x,60,'День '+(d+1),14)+`<rect x="${x-34}" y="77" width="68" height="66" rx="9" fill="#daebe0"/>`+fpText(x,118,a,30,'#237e79');if(s>=4)out+=`<rect x="${x-34}" y="166" width="68" height="66" rx="9" fill="#f6dfd0"/>`+fpText(x,207,b,30,'#b94b29')}out+=fpText(320,264,s===2?'6 × 4 = 24 · не хватает двух рыб':s===3?'Два дня по 5 · четыре дня по 4 = 26':s===4?'Вторая строка: 4 + 4 + 5 + 5 + 5 + 5 = 28':'6 × 9 − 26 = 54 − 26 = 28',19);return fpSvg(out,'Порции рыб за шесть дней: первому 26, второму 28')}
