function fpCircleScene(s,f){const values=[6,'','','?','','',3];if(s>=1)values[1]=4;if(s>=2)values[5]=7;if(s>=4){values[2]=5;values[3]=1;values[4]=2}let out='';[170,270,370,470].forEach((x,i)=>out+=`<circle cx="${x}" cy="130" r="76" fill="none" stroke="${s===i+1?'#e9693e':'#9aafa3'}" stroke-width="${s===i+1?3:2}"/>`);values.forEach((n,i)=>{const x=170+i*50;out+=`<rect x="${x-15}" y="103" width="30" height="54" rx="5" fill="${i===3&&s>=4?'#c8e5d2':'#f4b68f'}" stroke="#536c69"/>`+fpText(x,139,n||'·',25)});out+=fpText(320,30,'В каждом круге сумма 10',21);if(s===1)out+=fpText(320,257,'6 + 4 = 10',23);if(s===2)out+=fpText(320,257,'7 + 3 = 10 · остались 1, 2, 5',21);if(s===3)out+=fpText(320,246,'Второй круг: ? + сосед = 6 → 1 и 5',18)+fpText(320,277,'Третий круг: ? + сосед = 3 → 1 и 2',18);if(s===4)out+=fpText(320,260,'Общее число у пар (1, 5) и (1, 2) — 1',20,'#237e79');if(s===5)out+=fpText(320,250,'6+4=10 · 4+5+1=10',20)+fpText(320,280,'1+2+7=10 · 7+3=10',20);return fpSvg(out,'Четыре пересекающихся круга с семью картами: '+values.join(', '))}
