function fpCaterpillarScene(s,f){if(s===0||s===1)return fpImage('caterpillar-parts.png',s===0?'Голова · яблоко · вишня · виноград · хвост':'К голове подходит круглый выступ, к хвосту — прямоугольная выемка',145);if(s===2)return fpCaterpillarFigure(1,'Одна часть тела: вишня');if(s===3)return '<div style="width:100%;display:grid;grid-template-columns:1fr;gap:6px">'+fpCaterpillarFigure(2,'Две части: вишня → яблоко')+fpCaterpillarFigure(3,'Две части: виноград → вишня')+'</div>';if(s===4)return fpCaterpillarFigure(4,'Три части: виноград → вишня → яблоко');if(s===5){let out=fpText(320,30,'Все возможные переходы',22);[['Голова','Виноград или вишня'],['Виноград','Вишня'],['Вишня','Яблоко или хвост'],['Яблоко','Хвост']].forEach(([a,b],i)=>{const y=65+i*55;out+=`<rect x="85" y="${y-22}" width="470" height="43" rx="9" fill="#e6eee1"/>`+fpText(180,y+6,a,19)+fpText(315,y+6,'→',22)+fpText(430,y+6,b,18)});return fpSvg(out,'Допустимые переходы деталей пазла: голова к винограду или вишне, виноград к вишне, вишня к яблоку или хвосту, яблоко к хвосту')}
return '<div style="width:100%;display:grid;grid-template-columns:1fr 1fr;gap:8px">'+fpCaterpillarFigure(1,'1: вишня')+fpCaterpillarFigure(2,'2: вишня → яблоко')+fpCaterpillarFigure(3,'3: виноград → вишня')+fpCaterpillarFigure(4,'4: виноград → вишня → яблоко')+'</div>'}
const FOUR_MAGIC_PAIRS=[[1,7],[2,6],[3,8],[4,5]];
function fpMagicScene(s,f){if(s===0)return fpImage('magic-cards.png','Лицевая сторона, оборот после переворота и четыре карты на столе',265);let out='';const pairCount=s===1?2:4;FOUR_MAGIC_PAIRS.forEach(([front,back],i)=>{const x=90+i*150;out+=`<rect x="${x-32}" y="51" width="64" height="78" rx="5" fill="#65ac94"/>`+fpText(x,102,front,36,'white');if(i<pairCount)out+=fpText(x,154,'↕',27)+`<rect x="${x-32}" y="175" width="64" height="78" rx="5" fill="#f5f29a"/>`+fpText(x,226,back,36);else out+=fpText(x,217,'?',30)});out+=fpText(320,28,s<3?'Каждая пара — две стороны одной карты':'Видны 5 и 6 → заняты карты с 4 и 2',20);if(s>=3){for(const i of [1,3])out+=`<path d="M${90+i*150-38} 45L${90+i*150+38} 260" stroke="#e9693e" stroke-width="3"/>`;out+=fpText(320,290,s===3?'Остались зелёные стороны 1 и 3':'1 + 3 = 4',22,'#237e79')}return fpSvg(out,'Двусторонние карты: 1 с 7, 2 с 6, 3 с 8, 4 с 5. На закрытых картах 1 и 3')}
function fpFloorScene(s,f){if(s===0)return fpImage('floor-original.png','Оранжевые прямоугольники 23 × 11 см и одинаковые синие квадраты',240);if(s===1)return fpSvg(`<image href="assets/floor-original.png" x="85" y="15" width="483" height="218"/><rect x="115" y="71" width="89" height="44" fill="none" stroke="white" stroke-width="7"/><rect x="115" y="71" width="89" height="44" fill="none" stroke="#bd4f2a" stroke-width="3"/><path d="M115 118H139M181 118H204" fill="none" stroke="#096eae" stroke-width="7"/><path d="M139 118H181" stroke="#e9693e" stroke-width="7"/>`+fpText(320,261,'Выделен прямоугольник: длинный край — 23 см',19)+fpText(320,289,'Под ним: синий квадрат + короткий край + синий квадрат',17),'В исходном рисунке выделен длинный край прямоугольника и три прилегающих отрезка: квадрат, короткая сторона, квадрат');let out='';const base=137,width=46;out+=`<rect x="205" y="45" width="230" height="55" fill="#f0a03f" stroke="#536c69"/>`+fpText(320,80,'23 см',24);const lengths=[60,110,60],labels=s>=4?['6','11','6']:['a','11','a'];let x=205;lengths.forEach((w,i)=>{out+=`<rect x="${x}" y="${base}" width="${w}" height="${width}" fill="${i===1?'#f0a03f':'#2f95ca'}" stroke="#536c69"/>`+fpText(x+w/2,base+31,labels[i],24,i===1?'#172e34':'white');x+=w});out+=fpText(320,123,'=',25);if(s===2)out+=fpText(320,236,'a + 11 + a = 23',25);if(s===3)out+=fpText(320,236,'23 − 11 = 12 см — две стороны',23);if(s===4)out+=fpText(320,236,'12 : 2 = 6 см — одна сторона',23);if(s===5)out+=fpText(320,236,'6 + 11 + 6 = 23 см ✓',25,'#237e79');return fpSvg(out,'Сравнение длин: сторона квадрата плюс 11 см плюс сторона квадрата равны 23 см')}
